head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jlddst80300";
scwin.fnBookmarkSearch = null;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_pageBody = async function () {
    try {
        scwin.fnBookmark();
        await scwin.fnInit();
        $(".ord-07").attr("onclick", "fnSetSearchDate5('2024-01-01', '1'); fnSwapSearchBtnDates('7'); return false;");
        $("#cal_fromDate").change(function() {
                chkPeriod2Mil($(this).val());
        });

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jlddst80300.onpageload' }); }
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.fnBookmarkSearch = fnBookmarkSearch;
        await scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jlddst80300.onpageload' });
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
// [저작] 기간 프리셋 버튼 — fnDisplaySearchBtnDates 재설계 (btn_cm 텍스트·gcc date 조합)

/**
