 */
scwin.btn_pd_6m_onclick = function () { try { const to = WebSquare.date.getCurrentServerDate('yyyyMMdd'); const from = $c.date.addMonth(to, -6); const f = ($c.util.getComponent('cal_fromDate') || $c.util.getComponent('ipt_fromDate') || $c.util.getComponent('fromDate')); const t = ($c.util.getComponent('cal_toDate') || $c.util.getComponent('ipt_toDate') || $c.util.getComponent('toDate')); if (f && f.setValue) { f.setValue(from); } if (t && t.setValue) { t.setValue(to); } } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jlddst80300.pd_6m' }); } };

/**
 * @method
 * @name btn_pd_1y_onclick
 * @description 「1년」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_pd_1y_onclick = function () { try { const to = WebSquare.date.getCurrentServerDate('yyyyMMdd'); const from = $c.date.addYear(to, -1); const f = ($c.util.getComponent('cal_fromDate') || $c.util.getComponent('ipt_fromDate') || $c.util.getComponent('fromDate')); const t = ($c.util.getComponent('cal_toDate') || $c.util.getComponent('ipt_toDate') || $c.util.getComponent('toDate')); if (f && f.setValue) { f.setValue(from); } if (t && t.setValue) { t.setValue(to); } } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jlddst80300.pd_1y' }); } };

/**
 * @method
 * @name searchForm_onsubmit
 * @description searchForm onsubmit 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.searchForm_onsubmit = function(e){
    try {
        return false;

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jlddst80300.searchForm_onsubmit' }); }
};

/**
 * @method
 * @name btn_findCompanyName_onclick
 * @description btn_findCompanyName 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_findCompanyName_onclick = function(e){
    try {
        Promise.resolve($c.win.openPopup('/jldfil00033/jldfil00033.xml', { id: "pop_corp_std" }, { method: "loadInitPage" })).then(function (r) { if (!r) return; let a = Array.isArray(r) ? r : [r]; if (a[0] && a[0].__sdd_rec) { const rec = a[0]; const nm = function (s) { return s.replace(/_/g, '').toLowerCase(); }; const ps = (String(scwin.setCorpInfo).match(/\(([^)]*)\)/) || ['', ''])[1].split(',').map(function (s) { return s.trim(); }).filter(Boolean); const nk = {}; for (let k in rec) nk[nm(k)] = rec[k]; a = ps.map(function (p) { return nk[nm(p)]; }); } try { scwin.setCorpInfo.apply(null, a); } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'popup-recv' }); } }); return false;

} catch (_ex) { $c.exception.handleError(_ex, { context: 'jlddst80300.btn_findCompanyName_onclick' }); }
};

/**
 * @method
 * @name btn_fnSearchCorpName_onclick
 * @description btn_fnSearchCorpName 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_fnSearchCorpName_onclick = async function(e){
    try {
        await scwin.fnSearchCorpName(); return false;

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jlddst80300.btn_fnSearchCorpName_onclick' }); }
};

/**
 * @method
 * @name btn_fnDownload_onclick
 * @description btn_fnDownload 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_fnDownload_onclick = async function(e){
    try {
        await scwin.fnDownload();return false;

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jlddst80300.btn_fnDownload_onclick' }); }
};

/**
 * @method
 * @name btn_fnGetCookieComCode_onclick
 * @description btn_fnGetCookieComCode 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_fnGetCookieComCode_onclick = async function(e){
    try {
        await scwin.fnGetCookieComCode();return false;

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jlddst80300.btn_fnGetCookieComCode_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fnDownload
 * @description fn Download 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fnDownload = async function () {
    const sbmOptions = {
        id: "tx_fnDownload",
        method: "post",
        action: "/valueup/disclsstat.do",
        ref: "dma_fnDownloadReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fnSearch_ajaxsubmit
 * @description fn Search ajaxsubmit 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fnSearch_ajaxsubmit = async function () {
    const sbmOptions = {
        id: "tx_fnSearch_ajaxsubmit",
        method: "post",
        action: "/valueup/disclsstat.do",
        ref: "dma_fnSearchAjaxsubmitReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name keyEvent
 * @description key Event 처리
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.keyEvent = async function (e) {
    if ($c.util.getKeyCode(typeof e !== 'undefined' && e ? e : (typeof event !== 'undefined' ? event : undefined)) === 13 || (typeof e !== 'undefined' && e === 13)) {
        if ($c.util.getKeyCode(event) === 13) {
            if (fnAKCKwdSearchCodeType(((document.searchForm || { elements: [] }).searchCorpName))) {
                await scwin.fnSearchCorpName();
            }
        }
    }
};

/**
 * @method
 * @name fnInit
 * @description fn Init 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnInit = async function () {
    // 수동 전환 필요: fnDisplaySearchBtnDates(N) / fnDisplaySearchBtnDatesOnlyPeriod(N) → 작업본 dateSetting 관례로 재설계 (조회 기간 프리셋)
    //   KRX 방향: 재설계 축 — 작업본 정답지 관례 = scwin.dateSetting() + 기간 버튼 핸들러(btn_3mon_onclick 등)가 캘린더 setValue 로 기간을 직접 세움(ULDINF05800 계열 실증). 1:1 대체 함수가 없고 속성 승격도 아님 — 조회 영역 저작 관례로 실현. 요청 명부에서 제외(재설계 분류).
    //   근거: catalog/function-map (이 주석은 고쳐 쓴 뒤 지우십시오)
    /* TODO Stage2: [sdd] 미실현(재설계 분류 #128): fnDisplaySearchBtnDates( "2 ') */
    await scwin.fnSearchInit();
};

/**
 * @method
 * @name fnSearchInit
 * @description fn Search Init 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnSearchInit = async function () {
    await scwin.fnOrder("1", "D");
};

/**
 * @method
 * @name fnOrder
 * @description fn Order 처리
 * @param {*} mode mode
 * @param {*} stat stat
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnOrder = async function (mode, stat) {
    $c.util.getComponent("dma_fnDownloadReq").set("orderMode", mode);
    $c.util.getComponent("dma_fnDownloadReq").set("orderStat", stat);
    $c.util.getComponent("dma_fnDownloadReq").set("pageIndex", "1");
    await scwin.fnSearch();
};

/**
 * @method
 * @name fnSearch
 * @description fn Search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnSearch = async function () {
    setTimeout(function() {
            AKCDiv.setStyle("display", "none");
        }, 200);
    const fromDate = $c.util.getComponent('cal_fromDate').getValue();
    const toDate = $c.util.getComponent('cal_toDate').getValue();
    if (!$c.date.isDate(fromDate)) {
        await $c.win.alert("시작일자 형식이 틀립니다");
        return;
    }
    if (!$c.date.isDate(toDate)) {
        await $c.win.alert("종료일자 형식이 틀립니다");
        return;
    }
    if (($c.util.getComponent("dma_fnDownloadReq").get("repIsuSrtCd") || '') !== "") {
        $c.util.getComponent("dma_fnDownloadReq").set("allRepIsuSrtCd", "");
    }
    $c.util.getComponent("dma_fnDownloadReq").set("searchCorpName", $c.util.getComponent('ipt_searchCorpName').getValue());
    if ($(document).find("select[id=ipt_currentPageSize]").val() != null) {
        $c.util.getComponent("dma_fnDownloadReq").set("currentPageSize", $(document).find("select[id=ipt_currentPageSize]").val());
    }
    $c.util.getComponent("dma_fnDownloadReq").set("method", "valueupDisclsStatSub");
    $c.util.getComponent("dma_fnDownloadReq").set("forward", "valueupDisclsStat_sub");
    await scwin.tx_fnSearch_ajaxsubmit();
};

/**
 * @method
 * @name fnSearchCallBack
 * @description fn Search Call Back 처리
 * @param {*} data 데이터
 * @returns {void}
 * @hidden N
 */
scwin.fnSearchCallBack = function (data) {
    $("#mainContents").empty().append(data);
    $("tr:even").addClass("active");
    /* TODO Stage2: [sdd] 미실현(재설계 분류 #128): fnLegendTooltip( " ') */
};

/**
 * @method
 * @name fnDownload
 * @description fn Download 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnDownload = async function () {
    const fromDate = $c.util.getComponent('cal_fromDate').getValue();
    const toDate = $c.util.getComponent('cal_toDate').getValue();
    if (!$c.date.isDate(fromDate)) {
        await $c.win.alert("시작일자 형식이 틀립니다");
        return;
    }
    if (!$c.date.isDate(toDate)) {
        await $c.win.alert("종료일자 형식이 틀립니다");
        return;
    }
    $("#searchForm").attr('onsubmit', '');
    $c.util.getComponent("dma_fnDownloadReq").set("searchCorpName", $c.util.getComponent('ipt_searchCorpName').getValue());
    $c.util.getComponent("dma_fnDownloadReq").set("currentPageSize", "3000");
    $c.util.getComponent("dma_fnDownloadReq").set("pageIndex", "1");
    $c.util.getComponent("dma_fnDownloadReq").set("method", "valueupDisclsStatSub");
    $c.util.getComponent("dma_fnDownloadReq").set("forward", "valueupDisclsStat_detail");
    await scwin.tx_fnDownload();
    $("#searchForm").attr('onsubmit', 'return false;');
};

/**
 * @method
 * @name fnSearch1
 * @description fn Search1 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnSearch1 = async function () {
    $c.util.getComponent("dma_fnDownloadReq").set("pageIndex", "1");
    $c.util.getComponent("dma_fnDownloadReq").set("currentPageSize", $(document).find("select[id=ipt_currentPageSize]").val());
    await scwin.fnSearch();
};

/**
 * @method
 * @name fnSearchCorpName
 * @description fn Search Corp Name 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnSearchCorpName = async function () {
    let val = $c.util.getComponent('ipt_searchCorpName').getValue(); if (val == null) { val = ''; }
    $c.util.getComponent("dma_fnDownloadReq").set("allRepIsuSrtCd", "");
    $c.util.getComponent("dma_fnDownloadReq").set("repIsuSrtCd", "");
    $c.util.getComponent("dma_fnDownloadReq").set("isurCd", "");
    $c.util.getComponent("dma_fnDownloadReq").set("pageIndex", "1");
    if (val !== "") {
        $c.util.getComponent("dma_fnDownloadReq").set("searchCorpName", $c.util.getComponent('ipt_searchCorpName').getValue());
        fnAKCKwdSearchCorpNameAll();
    } else {
        $c.util.getComponent("dma_fnDownloadReq").set("isurCd", "");
        await scwin.fnSearchInit();
    }
    $c.util.getComponent("dma_fnDownloadReq").set("repIsuSrtCd", "");
};

/**
 * @method
 * @name fnSearchCorpNameAllCallBack
 * @description fn Search Corp Name All Call Back 처리
 * @param {*} items items
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnSearchCorpNameAllCallBack = async function (items) {
    if (items.length === 1) {
        await scwin.fnSearchCorpCode(items[0].repisusrtcd.substring(1, 7), items[0].isurcd);
        fnSetCookieCrop(items);
    } else {
        if (items.length > 1) {
            Promise.resolve($c.win.openPopup('/jldfil00033/jldfil00033.xml', { id: "pop_corp_std" }, { method: "loadInitPage" })).then(function (r) { if (!r) return; let a = Array.isArray(r) ? r : [r]; if (a[0] && a[0].__sdd_rec) { const rec = a[0]; const nm = function (s) { return s.replace(/_/g, '').toLowerCase(); }; const ps = (String(scwin.setCorpInfo).match(/\(([^)]*)\)/) || ['', ''])[1].split(',').map(function (s) { return s.trim(); }).filter(Boolean); const nk = {}; for (let k in rec) nk[nm(k)] = rec[k]; a = ps.map(function (p) { return nk[nm(p)]; }); } try { scwin.setCorpInfo.apply(null, a); } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'popup-recv' }); } });
    } else {
        await scwin.fnSearchCorpCode('');
    }
}
};

/**
 * @method
 * @name fnSearchCorpCode
 * @description fn Search Corp Code 처리
 * @param {String} repIsuSrtCd repIsuSrtCd
 * @param {String} isurCd isurCd
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnSearchCorpCode = async function (repIsuSrtCd, isurCd) {
    $c.util.getComponent("dma_fnDownloadReq").set("repIsuSrtCd", repIsuSrtCd);
    $c.util.getComponent("dma_fnDownloadReq").set("isurCd", isurCd);
    if (repIsuSrtCd === "" || isurCd === "") {
        await $c.win.alert("조회한 회사명이 존재하지 않습니다. \n정확한 회사명을 입력해 주세요. \n회사명이 정확하지 않으시면 회사명 검색을 이용해주세요.");
    } else {
        await scwin.fnSearchInit();
    }
    isurCd = ($c.util.getComponent("dma_fnDownloadReq").get("isurCd") || '');
    repIsuSrtCd = ($c.util.getComponent("dma_fnDownloadReq").get("repIsuSrtCd") || '');
};

/**
 * @method
 * @name setCorpInfo
 * @description set Corp Info 처리
 * @param {String} isurCd isurCd
 * @param {String} kisComCd kisComCd
 * @param {String} repIsuSrtCd repIsuSrtCd
 * @param {String} comNm comNm
 * @param {*} comAbbrv comAbbrv
 * @param {*} isurSymbl isurSymbl
 * @param {*} fssUnqNo fssUnqNo
 * @returns {void}
 * @hidden N
 */
scwin.setCorpInfo = function (isurCd, kisComCd, repIsuSrtCd, comNm, comAbbrv, isurSymbl, fssUnqNo) {
    let str = "";
    str += "isurCd : " + isurCd + "\n";
    str += "kisComCd : " + kisComCd + "\n";
    str += "repIsuSrtCd : " + repIsuSrtCd + "\n";
    str += "comNm : " + comNm + "\n";
    str += "comAbbrv : " + comAbbrv + "\n";
    str += "isurSymbl : " + isurSymbl + "\n";
    str += "fssUnqNo : " + fssUnqNo + "\n";
    if (repIsuSrtCd === "") {
        repIsuSrtCd = isurCd;
    }
    $c.util.getComponent('ipt_searchCorpName').setValue(comAbbrv);
    $c.util.getComponent("dma_fnDownloadReq").set("isurCd", isurCd);
    $c.util.getComponent("dma_fnDownloadReq").set("repIsuSrtCd", repIsuSrtCd);
};

/**
 * @method
 * @name fnBookmark
 * @description fn Bookmark 처리
 * @returns {void}
 * @hidden N
 */
scwin.fnBookmark = function () {
    const cookieName = "krxComp";
    const cookies = $c.util.getSessionStorage(cookieName);
    if (cookies != null) {
        (($c.util.getComponent('txt_myBookmark')) && ($c.util.getComponent('txt_myBookmark')).removeAll ? ($c.util.getComponent('txt_myBookmark')).removeAll() : (($c.util.getComponent('txt_myBookmark')) && ($c.util.getComponent('txt_myBookmark')).setValue ? ($c.util.getComponent('txt_myBookmark')).setValue('') : void 0));
        const items = cookies.split("/");
        let max = 0;
        for (i in items) {
            if (max === 10) {
                break;
            }
            const item = items[i].split(",");
            const repIsuSrtCd = item[1];
            const corpName = item[2];
            const isurcd = item[3];
            if (undefined !== corpName && undefined !== isurcd) {
                $("#txt_myBookmark").append("<a href='#' onclick=\"fnBookmarkSearch('" + repIsuSrtCd.substring(1, 7) + "','" + corpName + "'); return false;\" title=\"" + corpName + " 검색\" >" + corpName + "</a> ");
            }
            max++;
        }
    }
};

async function fnBookmarkSearch(repIsuSrtCd, corpName) {
    $c.util.getComponent('ipt_searchCorpName').setValue(corpName);
    $c.util.getComponent("dma_fnDownloadReq").set("repIsuSrtCd", repIsuSrtCd);
    await scwin.fnOrder("1", "D");
}

/**
 * @method
 * @name fnGetCookieComCode
 * @description fn Get Cookie Com Code 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnGetCookieComCode = async function () {
    const cookiesStr = scwin.fnGetCookie('krxComp');
    let totalArray;
    let newVal = "";
    let newComNm = "";
    if (cookiesStr != null) {
        totalArray = cookiesStr.split("/");
    }
    const j = 0;
    const sCookieVal = "";
    if (totalArray) {
        for (i = 0; j < 11 && i < totalArray.length - 1; i++) {
            const sCookieTemp = totalArray[i].split(",");
            if (i === 0) {
                newVal = newVal + sCookieTemp[1];
            } else {
                newVal = newVal + "," + sCookieTemp[1];
            }
            newComNm = sCookieTemp[2];
        }
    } else {
        await $c.win.alert("최근 검색한 회사가 없습니다.");
        return;
    }
    $c.util.getComponent("dma_fnDownloadReq").set("repIsuSrtCd", "");
    $c.util.getComponent("dma_fnDownloadReq").set("allRepIsuSrtCd", newVal);
    await scwin.fnSearch();
};

/**
 * @method
 * @name fnGetCookie
 * @description fn Get Cookie 처리
 * @param {*} keyname keyname
 * @returns {void}
 * @hidden N
 */
scwin.fnGetCookie = function (keyname) { const v = $c.util.getSessionStorage(keyname); return (v === undefined || v === null) ? '' : v; };
